head.script:
///////// 1. 변수 및 선언 영역 /////////
scwin.screenId = "jldinf10107";
scwin.init_line = 1;
scwin.redmpt_line = 0;

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.onpageload = async function () {
    try {
        scwin.init_recvParam();
        scwin.init_rowCopy();
        scwin.init_pageBody();
    } catch (e) {
        await $c.exception.handleError(e, { context: 'jldinf10107.onpageload' });
    }
};

/**
 * @method
 * @name init_rowCopy
 * @description dataList 단건 표시 복사 — 진입점에서 1회. 데이터 재적재 시 ev:ondataload 가 다시 부른다.
 * @returns {void}
 * @hidden N
 */
scwin.init_rowCopy = function () {
    const rows = [{ childId: "ipt_optionType", fn: function () { return String((dma_pageContext.get("optionType") ?? "")); } },
        { childId: "ipt_callLine", fn: function () { return String((dma_pageContext.get("callLine") ?? "")); } }];
    rows.forEach(function (it) {
        const c = $c.util.getComponent(it.childId);
        if (!c || typeof c.setValue !== "function") { return; }  // as-is 가 서버 렌더로 그리던 반복 행 — 산출에 없는 칸은 건너뛴다
        let v;
        try { v = it.fn(); } catch (e) { $c.exception.handleError(e, { notify: "none", context: "rowCopy:" + it.childId }); return; }
        if (v !== undefined && v !== null && String(v).trim() !== "") { c.setValue(String(v)); }
    });
};

/**
 * @method
 * @name init_pageBody
 * @description 초기화 — page Body
 * @returns {void}
 * @hidden N
 */
scwin.init_pageBody = function () {
    try {

        if( '' + dma_pageContext.get("redmpt_line") + '' === "" || '' + dma_pageContext.get("redmpt_line") + '' === "0" ){
            for(let i = 0 ; i < scwin.init_line ; i++){
                scwin.addRow(i+1);
                scwin.redmpt_line ++;
            }
        }else{
            scwin.redmpt_line = '' + dma_pageContext.get("redmpt_line") + '' === "" ? 0 : Number("" + dma_pageContext.get("redmpt_line") + "");
            for(let i = 0 ; i < scwin.redmpt_line ; i++){
                scwin.addRow(i+1);
            }
        }

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldinf10107.onpageload' }); }
};

/**
 * @method
 * @name init_recvParam
 * @description 화면 전환 파라미터 수신 — $c.data.getParameter() 를 dma_pageContext 에 담는다
 * @returns {void}
 * @hidden N
 */
scwin.init_recvParam = function () { dma_pageContext.setJSON($c.data.getParameter() ?? {}); };

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @name btn_AddRow_onclick
 * @description btn_AddRow 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 */
scwin.btn_AddRow_onclick = function(e){
    try {
        scwin.addRow()

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldinf10107.btn_AddRow_onclick' }); }
};

/**
 * @method
 * @name btn_DelRow_onclick
 * @description btn_DelRow 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 */
scwin.btn_DelRow_onclick = function(e){
    try {
        scwin.delRow()

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldinf10107.btn_DelRow_onclick' }); }
};

/**
 * @method
 * @name btn_sendForm_onclick
 * @description btn_sendForm 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_sendForm_onclick = async function(e){
    try {
        await scwin.send_form('__self.form')

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jldinf10107.btn_sendForm_onclick' }); }
};

/**
 * @method
 * @name btn_sendCancel_onclick
 * @description btn_sendCancel 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 */
scwin.btn_sendCancel_onclick = function(e){
    try {
        scwin.send_cancel()

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldinf10107.btn_sendCancel_onclick' }); }
};

/**
 * @method
 * @name table_13_oneditend
 * @description table_13 oneditend 이벤트
 * @param {Number} rowIndex 행 인덱스
 * @param {Number} columnIndex 열 인덱스
 * @param {*} value value
 * @returns {void}
 * @hidden N
 */
scwin.table_13_oneditend = function (rowIndex, columnIndex, value) {  };

///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name addRow
 * @description add Row 처리
 * @returns {void}
 * @hidden N
 */
scwin.addRow = function () { const d = $c.util.getComponent('dlt_call'); if (d && d.insertRow) { d.insertRow(); } };

/**
 * @method
 * @name delRow
 * @description del Row 처리
 * @returns {void}
 * @hidden N
 */
scwin.delRow = function () {
    if (scwin.redmpt_line > 0) {
        $("#tr_call_" + scwin.redmpt_line).remove();
        scwin.redmpt_line--;
    }
};

/**
 * @method
 * @name send_form
 * @description send form 처리
 * @param {*} fm fm
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.send_form = async function (fm) {
    ((($c.data.getParameter() && typeof $c.data.getParameter() === 'object' && Object.keys($c.data.getParameter()).length) ? $c.data.getParameter() : scwin.openerScwin()).div_redmpt).innerHTML = "";
    if (scwin.redmpt_line > 0) {
        for (let i = 0; i < scwin.redmpt_line; i++) {
            if ($c.str.getByteLength($("#int_pay_dd" + (i + 1)).val()) === 0) {
                await $c.win.alert("이자지급일을 입력하세요.");
                /* TODO Stage2: [sdd] 미실현 동작: set_focus (대상 미해석) — 전환 미완 */ /* unresolved-target intent:set_focus — {target}.focus({args}) */
                return;
            }
            if ($c.str.getByteLength($("#redmpt_amt" + (i + 1)).val()) === 0) {
                await $c.win.alert("상환금액을 입력하세요.");
                /* TODO Stage2: [sdd] 미실현 동작: set_focus (대상 미해석) — 전환 미완 */ /* unresolved-target intent:set_focus — {target}.focus({args}) */
                return;
            }
            if ($c.str.getByteLength($("#coupn_rt" + (i + 1)).val()) === 0) {
                await $c.win.alert("이자율을 입력하세요.");
                /* TODO Stage2: [sdd] 미실현 동작: set_focus (대상 미해석) — 전환 미완 */ /* unresolved-target intent:set_focus — {target}.focus({args}) */
                return;
            }
            if ($c.str.getByteLength($("#redmpt_pd_int_tp_cd" + (i + 1)).val()) === 0) {
                await $c.win.alert("거치기간이자를 입력하세요.");
                /* TODO Stage2: [sdd] 미실현 동작: set_focus (대상 미해석) — 전환 미완 */ /* unresolved-target intent:set_focus — {target}.focus({args}) */
                return;
            }
        }
    } else {
        await $c.win.alert("불균등 상세내역을 입력하세요.");
        return;
    }
    ((scwin.opener().getComponentById("redmpt_line")) && (scwin.opener().getComponentById("redmpt_line")).setValue ? (scwin.opener().getComponentById("redmpt_line")).setValue(scwin.redmpt_line) : (console.warn('[sdd] 부모 컴포넌트 미해결: ' + "redmpt_line"), void (scwin.redmpt_line)));
    let htmlStr = "";
    for (let i = 0; i < scwin.redmpt_line; i++) {
        const int_pay_dd = $("#int_pay_dd" + (i + 1)).val();
        const redmpt_amt = $("#redmpt_amt" + (i + 1)).val();
        const coupn_rt = $("#coupn_rt" + (i + 1)).val();
        const redmpt_pd_int_tp_cd = $("#redmpt_pd_int_tp_cd" + (i + 1)).val();
        htmlStr += "<input type='hidden' name='int_pay_dd' id='int_pay_dd" + (i + 1) + "' value='" + int_pay_dd + "' />";
        htmlStr += "<input type='hidden' name='redmpt_amt' id='redmpt_amt" + (i + 1) + "' value='" + redmpt_amt + "' />";
        htmlStr += "<input type='hidden' name='redmpt_coupn_rt_list' id='redmpt_coupn_rt_list" + (i + 1) + "' value='" + coupn_rt + "' />";
        htmlStr += "<input type='hidden' name='redmpt_pd_int_tp_cd_list' id='redmpt_pd_int_tp_cd_list" + (i + 1) + "' value='" + redmpt_pd_int_tp_cd + "' /></br>";
    }
    opener.$("#div_redmpt").append(htmlStr);
    $c.win.closePopup();
};

/**
 * @method
 * @name send_cancel
 * @description send cancel 처리
 * @returns {void}
 * @hidden N
 */
scwin.send_cancel = function () {
    $c.win.closePopup();
};

/**
 * @method
 * @name opener
 * @description 부모 화면 scope(browserPopup/pageFramePopup 공통 — $c.win.getOpenerScope). 단독 진입이거나 부모가 닫혀 없으면
 * @returns {Object} 부모 화면 scope 또는 빈 scope
 * @hidden N
 */
scwin.opener = function () {
    const scope = ($c.win && $c.win.getOpenerScope) ? $c.win.getOpenerScope() : null;
    return scope || { getComponentById: function () { return null; }, scwin: {} };
};

/**
 * @method
 * @name openerScwin
 * @description 부모 화면의 scwin(함수·전역 접근용). 부모가 없으면 빈 객체
 * @returns {Object} 부모 scwin 또는 {}
 * @hidden N
 */
scwin.openerScwin = function () {
    return scwin.opener().scwin || {};
};
